package org.jsoup.nodes;

import org.junit.Assert;
import org.junit.Test;
import org.jsoup.parser.ParseSettings;
import org.jsoup.parser.Parser;

public class CommentTest {

    @Test
    public void CommentConstructionTest() {
        String data = "Test Comment";
        Comment comment = new Comment(data);
        Assert.assertEquals(data, comment.getData());
    }

    @Test
    public void nodeNameTest() {
        Comment comment = new Comment("Test Comment");
        Assert.assertEquals("#comment", comment.nodeName());
    }

    @Test
    public void getDataTest() {
        String data = "Test Comment";
        Comment comment = new Comment(data);
        Assert.assertEquals(data, comment.getData());
    }

    @Test
    public void setDataTest() {
        String data = "Test Comment";
        Comment comment = new Comment("Initial Comment");
        comment.setData(data);
        Assert.assertEquals(data, comment.getData());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException{
        String data = "Test Comment";
        Comment comment = new Comment(data);
        StringBuilder accum = new StringBuilder();

        comment.outerHtmlHead(accum, 0, new Document.OutputSettings());

        Assert.assertEquals("<!--Test Comment-->", accum.toString());
    }

    @Test
    public void outerHtmlTailTest() {
        String data = "Test Comment";
        Comment comment = new Comment(data);
        StringBuilder accum = new StringBuilder();

        comment.outerHtmlTail(accum, 0, new Document.OutputSettings());

        Assert.assertEquals("", accum.toString());
    }

    @Test
    public void toStringTest() {
        String data = "Test Comment";
        Comment comment = new Comment(data);

        Assert.assertEquals("<!--Test Comment-->", comment.toString());
    }

    @Test
    public void cloneTest() {
        String data = "Test Comment";
        Comment comment = new Comment(data);
        Comment cloneComment = comment.clone();

        Assert.assertEquals(comment.getData(), cloneComment.getData());
        Assert.assertNotSame(comment, cloneComment);
    }

    @Test
    public void isXmlDeclarationTest() {
        String data = "Test Comment";
        Comment comment = new Comment(data);

        Assert.assertFalse(comment.isXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationTest() {
        String data = "Test Comment";
        Comment comment = new Comment(data);

        Assert.assertNull(comment.asXmlDeclaration());
    }
